export type OutcomeCode = 0 | 1 | 2 | 3; // disabled | fail | pass | na

export const OutcomeCodes = {
  DISABLED: 0 as OutcomeCode,
  FAIL: 1 as OutcomeCode,
  PASS: 2 as OutcomeCode,
  NA: 3 as OutcomeCode,
} as const;

export function encodeBase64Url(data: string): string {
  return btoa(data)
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/, '');
}

function createMinimalHeader(header: SeedHeader): Record<string, unknown> {
  const minimal: Record<string, unknown> = {
    c: header.c,
    n: header.n,
  };

  // Add subject if present (maintaining key order: sc, n, e)
  if (header.s) {
    minimal.s = {
      sc: header.s.sc,
      n: header.s.n,
    };
    if (header.s.e !== undefined) {
      minimal.s.e = header.s.e;
    }
  }

  return minimal;
}

export function packOutcomesToBytes(outcomes: OutcomeCode[]): Uint8Array {
  const numBytes = Math.ceil(outcomes.length / 4);
  const bytes = new Uint8Array(numBytes);

  for (let i = 0; i < outcomes.length; i++) {
    const byteIndex = Math.floor(i / 4);
    const bitOffset = (i % 4) * 2;
    bytes[byteIndex] |= (outcomes[i] << bitOffset);
  }

  return bytes;
}

export function encodeVarint(value: number): Uint8Array {
  const bytes: number[] = [];

  while (value >= 0x80) {
    bytes.push((value & 0x7F) | 0x80);
    value >>>= 7;
  }
  bytes.push(value & 0x7F);

  return new Uint8Array(bytes);
}

export function encodeSeed(seedData: SeedData, options: EncodeOptions = {}): EncodeResult {
  const { header, outcomes } = seedData;
  const { forceSparse = false, sparseThreshold = 0.8 } = options;

  // Analyze if sparse would be better
  const sparseAnalysis = shouldUseSparseEncoding(outcomes, sparseThreshold);

  if (sparseAnalysis.useSparse || forceSparse) {
    // Use sparse mode
    const encodedPayload = encodeSparsePayload(outcomes, sparseAnalysis.defaultOutcome);
    workingHeader.d = sparseAnalysis.defaultOutcome;
    isSparse = true;
  } else {
    // Use flat mode
    const encodedPayload = encodeFlatPayload(outcomes);
    isSparse = false;
  }

  const encodedHeader = encodeHeader(workingHeader);
  return {
    seedFragment: `#seed=v2.${encodedHeader}.${encodedPayload}`,
    isSparse,
    compressionRatio
  };
}

describe('Flat mode encoding/decoding', () => {
  it('should encode and decode simple outcomes correctly', () => {
    const outcomes: OutcomeCode[] = [2, 2, 1, 3, 0]; // pass, pass, fail, na, disabled
    const seedData = createSeedData(sampleCommit, 5, outcomes);

    const encoded = encodeSeed(seedData);
    expect(encoded.seedFragment).toMatch(/^#seed=v2\./);

    const decoded = decodeSeed(encoded.seedFragment);
    expect(decoded.outcomes).toEqual(outcomes);
  });
});

